import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第六十二卦 小過 雷山小過 震上艮下","description":"周易 - 第六十二卦 小過 雷山小過 震上艮下","frontmatter":{"title":"第六十二卦 小過 雷山小過 震上艮下","description":"周易 - 第六十二卦 小過 雷山小過 震上艮下"},"headers":[],"relativePath":"classics/zhouyi/063.md","filePath":"classics/zhouyi/063.md"}'),l={name:"classics/zhouyi/063.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="小過" tabindex="-1">小過 <a class="header-anchor" href="#小過" aria-label="Permalink to “小過”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨，利貞，可小事，不可大事。飛鳥遺之音，不宜上宜下，大吉。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>小過，小者過而亨也。過以利貞，與時行也。柔得中，是以小事吉也。剛失位而不中，是以不可大事也。有飛鳥之象焉，有飛鳥遺之音，不宜上宜下，大吉；上逆而下順 也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山上有雷，小過；君子以行過乎恭，喪過乎哀，用過乎儉。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>飛鳥以兇。象 曰：飛鳥以兇，不可如何也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>過其祖，遇其妣；不及其君，遇其臣；無咎。象曰：不及其君，臣不可過也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>弗過防之，從或戕之，兇。象曰：從或戕之，兇如何也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>無咎，弗過遇之。往厲必戒，勿用永貞。象曰：弗過遇之，位不當也。往厲必戒，終不可長也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>密雲不雨，自我西郊，公弋取彼在穴。象曰：密雲不雨，已上也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>弗遇過之，飛鳥離之，兇，是謂災眚。象曰：弗遇過之，已亢也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
